def msg_text(m):
    t=m["type"]
    if t=="普通文本":
        return m.get("content","")
    if t=="引用消息":
        cd=m.get("contentData",{})
        # include reply title/content
        parts=[]
        if cd.get("title"): parts.append(cd["title"])
        if cd.get("content") and cd.get("content")!=cd.get("title"): parts.append(cd["content"])
        qc=cd.get("quotedContent")
        if qc: parts.append(f"[引:{qc}]")
        return " ".join(parts)
    if t=="图片":
        return "[图片]"
    if t=="系统消息":
        return "[系统] "+m.get("content","")
    if t=="合并转发":
        return "[合并转发] "+m.get("content","")
    return f"[{t}] "+m.get("content","")
# print first 250 lines
for i,m in enumerate(msgs[:250]):
    print(i, m["datetime"][11:16], m.get("name"), ":", msg_text(m)[:250].replace("\n"," / "))

